+ function sessionFrom(value: unknown): SavedSession | null {
+   const saved = value as Partial<{
+     mode: string
+     folder: string
+     name: string
+     link: string
+     home: unknown
+     shared: unknown
+   }> | null
+   if (!saved || typeof saved.folder !== 'string' || typeof saved.name !== 'string') return null
